/* The revision's zone sub-packets, by the ordinal that leads each. */
static int
zone_sub(RsprotBuf* c, struct PktZoneSubPacket* out)
{
    int ordinal;

    if( rsprot_buf_readable(c) <= 0 || c->err )
        return -1;
    ordinal = rsprot_g1(c);
    memset(out, 0, sizeof(*out));
    switch( ordinal )
    {
    case 0: /* LOC_ANIM */
    {
        MsgLocAnim m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_loc_anim_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_loc_anim(&m, out);
    }
    case 1: /* OBJ_CUSTOMISE */
    {
        MsgObjCustomise m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_obj_customise_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        (void)m;
        return 2; /* read; no canonical arm */
    }
    case 2: /* OBJ_DEL */
    {
        MsgObjDel m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_obj_del_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_obj_del(&m, out);
    }
    case 3: /* OBJ_COUNT */
    {
        MsgObjCount m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_obj_count_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_obj_count(&m, out);
    }
    case 4: /* OBJ_ENABLED_OPS */
    {
        MsgObjEnabledOps m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_obj_enabled_ops_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_obj_enabled_ops(&m, out);
    }
    case 5: /* LOC_DEL */
    {
        MsgLocDel m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_loc_del_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_loc_del(&m, out);
    }
    case 6: /* LOC_ADD_CHANGE_V2 */
    {
        MsgLocAddChangeV2 m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        prep_loc_add_change_v2(&m);
        rsprot_exec_decode(&x, c);
        packet_loc_add_change_v2_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_loc_add_change_v2(&m, out);
    }
    case 7: /* MAP_PROJANIM_V2 */
    {
        MsgMapProjAnimV2 m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_map_projanim_v2_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_map_projanim_v2(&m, out);
    }
    case 8: /* SOUND_AREA */
    {
        MsgSoundArea m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_sound_area_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_sound_area(&m, out);
    }
    case 9: /* OBJ_UNCUSTOMISE */
    {
        MsgObjUncustomise m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_obj_uncustomise_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        (void)m;
        return 2; /* read; no canonical arm */
    }
    case 10: /* LOC_MERGE */
    {
        MsgLocMerge m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_loc_merge_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_loc_merge(&m, out);
    }
    case 11: /* MAP_ANIM */
    {
        MsgMapAnim m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_map_anim_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_map_anim(&m, out);
    }
    case 12: /* OBJ_ADD */
    {
        MsgObjAdd m;
        RsprotExec x;

        memset(&m, 0, sizeof(m));
        rsprot_exec_decode(&x, c);
        packet_obj_add_osrs238_out(&x, &m);
        if( !rsprot_exec_ok(&x) || c->err )
            return 0;
        return adapt_zone_obj_add(&m, out);
    }
    default:
        return 0;
    }
}

/* IF_BUTTON, opcode 43 */
static int
out_if_button(struct ProtoOutArgs const* a, RsprotBuf* b)
{
    MsgIf1Button m;
    RsprotExec x;

    memset(&m, 0, sizeof(m));
    w_if_button(&m, a);
    rsprot_exec_encode(&x, b);
    packet_if_button_osrs238_in(&x, &m);
    if( b->err )
        return 0; /* it does not fit the caller's buffer */
    /* Arguments the layout cannot carry are the caller's bug. */
    assert(rsprot_exec_ok(&x));
    return 1;
}

